      "id": "AC-2",
      "description": "Percentage(True) and Percentage(False) each raise loanflow.errors.ValidationError at construction time (bool must be rejected even though bool is an int subclass in Python)."
    },
    {
      "id": "AC-3",
      "description": "Percentage(-1) still raises loanflow.errors.ValidationError (the existing negative-value validation in __post_init__ must remain intact and unregressed)."
    },
    {
      "id": "AC-4",
      "description": "Valid construction paths are unaffected: Percentage(3650) succeeds, and Percentage.from_ratio(0.365).as_percent_string() still returns '36.50%' exactly as before."
    },
    {
      "id": "AC-5",
      "description": "demo-repo/tests/unit/test_primitives.py contains at least one new regression test asserting the non-integer/bool basis_points rejection, and the full narrow test file (demo-repo/tests/unit/test_primitives.py) passes."
    }
  ],
  "task_graph": [
    {
      "id": "N-RESEARCH",
      "description": "Confirm, with file:line citations, the exact shape of Money.__post_init__'s validation pattern, Percentage's current __post_init__ and as_percent_string bodies, the ValidationError import path, and that no existing call site constructs Percentage with a non-int value (so this fix cannot regress any current caller).",
      "phase": "research",
      "depends_on": []
    },
    {
      "id": "N-IMPLEMENT",
      "description": "Add the isinstance(bool)/isinstance(int) type check to Percentage.__post_init__ mirroring Money's pattern, preceded by a failing regression test in demo-repo/tests/unit/test_primitives.py written first (TDD).",
      "phase": "implementation",
      "depends_on": [
        "N-RESEARCH"
      ]
    },
    {
      "id": "N-VERIFY",
      "description": "Independently re-run the narrow test file (demo-repo/tests/unit/test_primitives.py) and confirm every acceptance criterion against real command output.",
      "phase": "verification",
      "depends_on": [
        "N-IMPLEMENT"
      ]
    }
  ],
  "status": "approved"
}
